#include <stdio.h>
#include <stdlib.h>
enum{ADD=1,MUL,SOU,DIV,COP,AFC,JMP,JMF,INF,SUP,EQU,PRI,ADR,LDP,STP};typedef struct{int o,a,b,c;}I;int main(int ac,char**av){if(ac!=2)return 2;FILE*f=fopen(av[1],"r");if(!f)return 2;I p[8192];long m[4096]={0};int n=0;while(n<8192&&fscanf(f,"%d",&p[n].o)==1){int k=(p[n].o==ADD||p[n].o==MUL||p[n].o==SOU||p[n].o==DIV||p[n].o==INF||p[n].o==SUP||p[n].o==EQU||p[n].o==ADR||p[n].o==LDP||p[n].o==STP)?3:(p[n].o==AFC||p[n].o==COP||p[n].o==JMF?2:1);if(fscanf(f,"%d",&p[n].a)!=1||(k>1&&fscanf(f,"%d",&p[n].b)!=1)||(k>2&&fscanf(f,"%d",&p[n].c)!=1))return 2;n++;}fclose(f);for(int pc=0;pc<n;pc++){I x=p[pc];if(x.o==ADD)m[x.a]=m[x.b]+m[x.c];else if(x.o==MUL)m[x.a]=m[x.b]*m[x.c];else if(x.o==SOU)m[x.a]=m[x.b]-m[x.c];else if(x.o==DIV){if(!m[x.c])return 1;m[x.a]=m[x.b]/m[x.c];}else if(x.o==COP)m[x.a]=m[x.b];else if(x.o==AFC)m[x.a]=x.b;else if(x.o==ADR)m[x.a]=x.b;else if(x.o==LDP)m[x.a]=m[m[x.b]];else if(x.o==STP)m[m[x.a]]=m[x.b];else if(x.o==JMP)pc=x.a-1;else if(x.o==JMF&&!m[x.a])pc=x.b-1;else if(x.o==INF)m[x.a]=m[x.b]<m[x.c];else if(x.o==SUP)m[x.a]=m[x.b]>m[x.c];else if(x.o==EQU)m[x.a]=m[x.b]==m[x.c];else if(x.o==PRI)printf("%ld\n",m[x.a]);}return 0;}
